import{c as i,U as e,h as a,l as n}from"./chunks/framework.C0iWzFTI.js";const r="/blog/assets/RocketMQ-5.x%E9%83%A8%E7%BD%B2%E6%9E%B6%E6%9E%84.drawio.DMAE3-Gy.png",u=JSON.parse('{"title":"常见术语","description":"","frontmatter":{},"headers":[],"relativePath":"7-消息队列/RocketMQ/常用术语.md","filePath":"7-消息队列/RocketMQ/常用术语.md"}'),l={name:"7-消息队列/RocketMQ/常用术语.md"};function t(p,s,o,h,k,c){return e(),a("div",null,s[0]||(s[0]=[n(`<h1 id="常见术语" tabindex="-1">常见术语 <a class="header-anchor" href="#常见术语" aria-label="Permalink to &quot;常见术语&quot;">​</a></h1><p>在安装 RocketMQ 的过程之中，我们实际上是执行了两步命令：</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nohup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rocketmq-all-5.2.0-bin-release/bin/mqnamesrv</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nohup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rocketmq-all-5.2.0-bin-release/bin/mqbroker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:9876</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --enable-proxy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这里启动了 NameServer、Broker、Proxy 这三个核心的组件，加上 Producer 和 Consumer 就构成了 RocketMQ 的整个体系结构</p><p><img src="`+r+'" alt=""></p><p>当服务启动时，Broker 向 NameServer 注册路由信息。Proxy 获取路由信息。Producer 发送消息至 Proxy，Proxy 通过路由信息，找到对应的 Broker，由 Broker 进行信息的存储。</p><p>消息发送完成后，消息就被划分到 Topic 的不同的队列中，等待消费。RocketMQ 将消费者进行了分类，分为了：</p><ul><li>PushConsumer：服务端主动推送消息到客户端，客户端只需要处理收到消息后的业务逻辑</li><li>SimpleConsumer：客户端主动拉取消息，处理完成消息后，主动向服务端确定消息已经被成功消费</li><li>PullConsumer</li></ul><p>在 RocketMQ 中，多个消费者示例构成了 <strong>消费者组</strong>，这里有个重要的规则：<strong>同一条消费只能够被消费者组内的一个消费者消费</strong>，引入消费者组的设计，有两个方面的好处：</p><ul><li>多个消费者同时消费，提升了消费端的消费能力。</li><li>能够保证当一个消费者宕机后，同组之中的消费者也能够继续消费</li></ul><p>其中对于第一点，RocketMQ 称之为 “<strong>共享消费</strong>”，当然了也可以不采用这种方式，可以让消费者组内只有一个消费者消费，这种消费策略称之为 “<strong>广播消费</strong>”。</p><p>那么，在常用的<strong>共享消费的模式</strong>下，消息是如何在消费者组内做负载均衡的呢？这里有两种不同的方式：</p><ul><li>消息粒度：同一个Topic中的消息，将会被消费者组内的多个消费者平摊，这也就意味着一个队列会被同一个消费者组内的多个消费者消费</li><li>队列粒度：同一个Topic中一个队列的消息，只会被同一个消费者内的一个消费者消费</li></ul><p>其中，消息粒度的负载均衡是 PushConsumer 和 SimpleConsumer 的默认消费策略，队列粒度是 PullConsumer 的默认消费策略。</p>',14)]))}const m=i(l,[["render",t]]);export{u as __pageData,m as default};
